code_question:
def solution(W, V, C):
    n = len(W)
    # Initialize the DP table
    dp = [[0] * (C + 1) for _ in range(n + 1)]

    # Build up the table by iterating over items and capacities
    for i in range(1, n + 1):
        for w in range(1, C + 1):
            if W[i - 1] <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w-W[i-1]] + V[i-1])
            else:
                dp[i][w] = dp[i-1][w]

    return dp[n][C]

