code_question:
def solution(weights):
    min_diff = float('inf')
    total_sum = sum(weights)
    n = len(weights)
    dp = [[False] * (total_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True
    if weights[0] <= total_sum:
        dp[1][weights[0]] = True
    for i in range(2, n + 1):
        for j in range(total_sum + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= weights[i - 1]:
                dp[i][j] |= dp[i - 1][j - weights[i - 1]]
    for j in range(total_sum // 2, -1, -1):
        if dp[n][j]:
            min_diff = total_sum - 2 * j
            break
    return min_diff

weights = [9, 5]
solution(weights)

