def solution(weights):
    from itertools import combinations
    total_sum = sum(weights)
    half_sum = total_sum // 2
    dp = {0: 0}
    for weight in weights:
        next_dp = dp.copy()
        for val in sorted(dp.keys(), reverse=True):
            if dp[val] + weight <= half_sum:
                next_dp[val + weight] = max(next_dp.get(val + weight, 0), dp[val] + weight)
        dp = next_dp
    min_diff = min(total_sum - 2 * val for val in dp.values())
    return min_diff

