def solution():
    from itertools import combinations
    weights = [28, 2, 15, 29, 32, 15, 23, 15]
    total_sum = sum(weights)
    half_sum = total_sum // 2
    min_diff = float('inf')
    n = len(weights)
    dp = [[False] * (half_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    # Filling the DP table
    for i in range(1, n + 1):
        for j in range(half_sum + 1):
            if j >= weights[i-1]:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-weights[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # Finding the minimum difference
    for j in range(half_sum, -1, -1):
        if dp[n][j]:
            min_diff = total_sum - 2 * j
            break
    return str(min_diff)

