def solution():
    # Define the graph as a dictionary where each key is a node and its value is a list of tuples representing edges and their weights
    graph = {
        0: [],
        1: [(3, 2)],
        2: [(0, 6), (1, 5), (3, 3)],
        3: [(0, 3)]
    }

    # Initialize distances to infinity and track previous nodes
    distances = {node: float('infinity') for node in graph}
    previous_nodes = {node: None for node in graph}
    distances[0] = 0

    # Dijkstra's algorithm
    unvisited_nodes = list(graph.keys())
    while unvisited_nodes:
        current_node = min(unvisited_nodes, key=lambda node: distances[node])
        unvisited_nodes.remove(current_node)

        for neighbor, weight in graph[current_node]:
            tentative_distance = distances[current_node] + weight
            if tentative_distance < distances[neighbor]:
                distances[neighbor] = tentative_distance
                previous_nodes[neighbor] = current_node

    # Reconstruct the path from 0 to 3
    path = []
    current_node = 3
    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]
    path.reverse()

    return path, distances[3]

