code_question:
def solution(start=0, end=3):
    # Define the graph
    graph = {
        0: {3: 4},
        1: {0: 1, 3: 5, 2: 1},
        2: {3: 1},
        3: {}
    }

    # Initialize distances dictionary with infinity for each node except start node
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    # Use a priority queue to manage nodes to be visited next
    visited = set()
    import heapq
    queue = [(0, start)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)
        if current_node == end:
            break

        if current_node in visited:
            continue
        visited.add(current_node)

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    # Reconstruct the path
    path = []
    node = end
    while node != start:
        for neighbor, weight in graph.items():
            if neighbor in path and node in graph[neighbor] and distances[node] == distances[neighbor] + graph[neighbor][node]:
                path.append(neighbor)
                node = neighbor
                break
    path.append(start)
    path.reverse()

    return path, distances[end]

solution()

