code_question:
def solution():
    import pulp as pl
    # Define the graph and its structure
    edges = {('3', '1'): 4, ('1', '2'): 4, ('1', '0'): 5, ('0', '3'): 1, ('2', '3'): 1}
    nodes = ['0', '1', '2', '3']
    start_node = '0'
    end_node = '3'
    node_id = {}
    for i, node in enumerate(nodes):
        node_id[node] = i

    # Initialize model
    prob = pl.LpProblem('Shortest Path Problem', pl.LpMinimize)
    x = {}
    for edge in edges:
        x[edge] = pl.LpVariable(f'x{node_id[edge[0]]}{node_id[edge[1]]}', lowBound=0, cat='Continuous')
    # Objective function
    prob += pl.lpSum([edges[edge] * x[edge] for edge in edges]), 'Total Weight'

    # Constraints
    for node in nodes:
        if node != start_node and node != end_node:
            prob += pl.lpSum([x[edge] for edge in edges.keys() if edge[1] == node]) == pl.lpSum([x[edge] for edge in edges.keys() if edge[0] == node]), f'Supply {node}'
    prob += pl.lpSum([x[edge] for edge in edges.keys() if edge[1] == end_node]) - pl.lpSum([x[edge] for edge in edges.keys() if edge[0] == end_node]) == 1, f'Demand {end_node}'
    prob += pl.lpSum([x[edge] for edge in edges.keys() if edge[1] == start_node]) - pl.lpSum([x[edge] for edge in edges.keys() if edge[0] == start_node]) == -1, f'Start {start_node}'

    prob.solve()
    path = []
    for edge in edges:
        if x[edge].varValue > 0.5:
            path.append((node_id[edge[0]], node_id[edge[1]]))
    total_distance = sum(edges[edge]*x[edge].varValue for edge in edges)
    return [node_id[edge[0]] for edge in sorted(path)] + [node_id[path[-1][-1]]], int(total_distance)

