def solution():
    from collections import defaultdict
    import heapq

    # Define the graph
    graph = {
        0: {2: 2},
        1: {0: 6, 3: 2},
        2: {1: 5, 3: 4},
        3: {}
    }

    # Function to calculate the shortest path using Dijkstra's algorithm
    def dijkstra(graph, start):
        distances = {vertex: float('inf') for vertex in graph}
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_vertex = heapq.heappop(priority_queue)

            if current_distance > distances[current_vertex]:
                continue

            for neighbor, weight in graph[current_vertex].items():
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    # Find the shortest path from node 0 to node 3
    shortest_distances = dijkstra(graph, 0)
    total_distance = shortest_distances[3]

    # Reconstruct the path
    path = [3]
    previous_vertex = None
    current_vertex = 3
    while current_vertex != 0:
        for predecessor, weight in graph.items():
            if current_vertex in weight and weight[current_vertex] == shortest_distances[current_vertex] - shortest_distances[predecessor]:
                path.append(predecessor)
                previous_vertex = predecessor
                current_vertex = predecessor
                break
    path.reverse()
    return path, total_distance

