def solution(participants):
    from functools import reduce
    from collections import defaultdict

    # Extract available slots for each participant
    available_slots = defaultdict(list)
    for id, info in participants.items():
        available_slots[id].extend(info['available_slots'])

    # Find the intersection of all available slots
    common_slots = reduce(set.intersection, map(set, available_slots.values()))
    if not common_slots:
        return []
    else:
        # Assuming we want the earliest slot if multiple options exist
        earliest_slot = min(common_slots)
        return {0: [earliest_slot]}

