    }
    num_slots = 4
    meeting_id = 1

    # Create a dictionary to store available timeslots
    possible_meeting_times = defaultdict(list)

    # Check each participant's availability
    for participant_id, details in participants.items():
        for slot in details['available_slots']:
            if slot in range(num_slots):
                # Check if the participant is associated with the meeting
                if meeting_id in details['meetings']:
                    possible_meeting_times[meeting_id].append(slot)

    # Find intersection of all available slots for the meeting
    common_timeslots = set(possible_meeting_times[meeting_id])
    for timeslots in possible_meeting_times.values():
        common_timeslots = common_timeslots.intersection(set(timeslots))

    # Convert to list and sort it
    common_timeslots = sorted(list(common_timeslots))

    return {meeting_id: common_timeslots}

