    import numpy as np

    # Define the participants and their available slots
    participants = {
        0: {'available_slots': [2, 3], 'meetings': [1]},
        1: {'available_slots': [0, 2], 'meetings': [1, 0]},
        2: {'available_slots': [0, 2, 3], 'meetings': [1]}
    }

    # Create a dictionary to hold possible meeting times based on the meetings
    possible_meetings_times = defaultdict(list)
    for participant_id, info in participants.items():
        for meeting_id in info['meetings']:
            possible_meetings_times[meeting_id].append(participant_id)

    # Find common available slot for each meeting
    meet2time = {}
    for meeting_id, participants_list in possible_meetings_times.items():
        available_timeslots = set(range(4))
        for participant in participants_list:
            available_timeslots.intersection_update(set(participants[participant]['available_slots']))
        if available_timeslots:
            meet2time[meeting_id] = list(available_timeslots)[0]
        else:
            meet2time[meeting_id] = None

    return dict(meet2time)

