def solution(participants):
    # Convert participants info into a dict for easier lookup
    available_times = {i['meetings'][0]: i['available_slots'] for i in participants.values()}
    all_possible_times = set(available_times[0])

    # Find the intersection of available times among all participants
    for meeting in available_times.keys():
        all_possible_times &= set(available_times[meeting])

    # Mapping the meetings to the possible time slots
    meet2time = {meeting: list(all_possible_times) for meeting in available_times.keys()}

    return meet2time

