code_question:
def solution():
    from typing import List, Tuple

    items = [(2, 3), (4, 4), (4, 4), (1, 1), (3, 5)] # (weight, value)
    capacity = 25
    n = len(items)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    selected_items = []

    for i in range(1, n + 1):
        for j in range(capacity + 1):
            weight, value = items[i - 1]
            if j >= weight:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - weight] + value)
            else:
                dp[i][j] = dp[i - 1][j]

    j = capacity
    for i in range(n, 0, -1):
        if dp[i][j] != dp[i - 1][j]:
            selected_items.append(i - 1)
            j -= items[i - 1][0]

    total_value = dp[n][capacity]
    feasible = True if total_value > 0 else False
    selected_item_ids = sorted(selected_items)

    return feasible, total_value, selected_item_ids

def solution():
    import pulp

    # Define the problem
    prob = pulp.LpProblem('graph_coloring', pulp.LpMinimize)

    # Variables
    color_choice = {}
    for i in range(1, 7):
        color_choice[i] = pulp.LpVariable.dicts(f'vertex_{i}', ['A', 'B', 'C'], cat='Binary')

    # Add constraints
    constraints = {
        1: [3],
        2: [3, 4],
        3: [1, 2, 4],
        4: [2, 3, 5, 6],
        5: [4],
        6: [4]
    }
    for v, neighbors in constraints.items():
        for u in neighbors:
            for c in ['A', 'B', 'C']:
                prob += color_choice[v][c] + color_choice[u][c] <= 1

    # Objective function (not really needed since we're just solving a feasibility problem)
    prob += 0

    # Solve
    prob.solve()
    if pulp.LpStatus[prob.status] != 'Optimal':
        raise Exception('No valid coloring found!')

    # Extract result
    result = {}
    for v in color_choice.keys():
        for c in ['A', 'B', 'C']:
            if color_choice[v][c].varValue == 1:
                result[v] = c
                break

    return result

