def solution():
    # Define the two strings
    str1 = 'ecf'
    str2 = 'def'

    # Initialize the matrix with dimensions (len(str1)+1) x (len(str2)+1)
    dp = [[0 for _ in range(len(str2)+1)] for _ in range(len(str1)+1)]

    # Fill in the base cases: if one string is empty, the distance is the length of the other string
    for i in range(len(str1)+1):
        dp[i][0] = i
    for j in range(len(str2)+1):
        dp[0][j] = j

    # Compute the edit distance using dynamic programming
    for i in range(1, len(str1)+1):
        for j in range(1, len(str2)+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j],       # Deletion
                                dp[i][j-1],       # Insertion
                                dp[i-1][j-1]) + 1 # Substitution

    return dp[len(str1)][len(str2)]

